section_card <- function(title,...,subtitle=NULL,class='') shiny::div(class=paste('rs-card',class),shiny::div(class='card-heading',shiny::h3(title),if(!is.null(subtitle))shiny::p(class='muted',subtitle)),...)
localization_inputs_ui <- function() tagList(
  section_card('Analysis setup',
    uiOutput('localization_status'),
    tags$details(id='analysis_advanced',tags$summary('Advanced · filters, ranges and calibration'),
      div(class='target-filter',numericInput('minimum_bp','Minimum candidate size (bp)',0,min=0),
        textInput('target_channel','Peak channel',''),actionButton('apply_preview_filter','Apply filter')),
      div(class='two-column',textInput('loc_name','Assay / primer-set name',''),
        div(style='display:none',textInput('loc_gene','Gene / locus',''))),
      textInput('loc_counting','Counted repeat definition',''),
      div(class='three-column',numericInput('loc_unit','bp per counted repeat',NA,min=.1),
        numericInput('loc_normal_max','Normal upper bound',NA,min=0),
        numericInput('loc_expanded_min','Expanded lower bound',NA,min=0)),
      div(class='two-column',checkboxInput('loc_normal_inclusive','Include normal upper bound',TRUE),
        checkboxInput('loc_expanded_inclusive','Include expanded lower bound',TRUE)),
      textInput('loc_source','Range source / version',''),
      actionButton('reset_gene_profile','Reset to gene defaults'),
      selectInput('loc_mode','Length conversion',c('Choose conversion'='','From matched reference / primers'='theoretical','Measured linear CE calibration'='linear'),selectize=FALSE),
      conditionalPanel("input.loc_mode === 'linear'",div(class='two-column',
        numericInput('loc_intercept','CE intercept (bp)',NA),numericInput('loc_slope','CE slope (bp / repeat)',NA,min=.01))),
      numericInput('loc_uncertainty','CE uncertainty ± bp (blank = unknown)',NA,min=0),
      textInput('loc_mapping_source','Mapping / uncertainty basis',''),
      p(class='status-small','Unknown uncertainty permits nominal research localization. Enter 0 only for an explicit zero-margin assumption.'),
      textOutput('filter_status')),
    actionButton('save_localization','Apply analysis setup',class='btn-primary'))
)
